var KEY='elzaAuto',DEF={refresh:true,hlidac:true,notif:false,link:true,plan:true},LOG=[],LASTOV=-1,TICK=0;
function auto(){var o={};try{o=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){}return Object.assign({},DEF,o)}
