var BASE=null,CFG={hide:[],grp:{},ren:{},ord:[],iord:[]},CFGID=0,CFGLOAD=0,LOCK=['dnes','navod','menu','sprava'],NEWG='+ nová skupina…';
function baseMenu(){if(!BASE)BASE=JSON.parse(JSON.stringify(MENU));return BASE}
function norm0(c){c=c&&typeof c=='object'?c:{};var ids={};baseMenu().forEach(function(g){g[1].forEach(function(i){ids[i[0]]=1})});var fh=function(a){return Array.isArray(a)?a.filter(function(v){return typeof v=='string'}):[]},fo=function(o){var r={};if(o&&typeof o=='object')Object.keys(o).forEach(function(k){if(typeof o[k]=='string'&&o[k].trim())r[k]=o[k].trim()});return r};var grp=fo(c.grp);Object.keys(grp).forEach(function(k){if(!ids[k])delete grp[k]});return{hide:fh(c.hide).filter(function(v){return ids[v]}),grp:grp,ren:fo(c.ren),ord:fh(c.ord),iord:fh(c.iord).filter(function(v){return ids[v]})}}
function build(c){var B=baseMenu(),gs=[],by={};
 B.forEach(function(g){var n=c.ren[g[0]]||g[0];var o={n:n,it:[]};gs.push(o);by[n]=o});
 B.forEach(function(g,gi){g[1].forEach(function(i){var t=c.grp[i[0]];if(t&&LOCK.indexOf(i[0])<0&&t!=gs[gi].n){if(!by[t]){var o={n:t,it:[]};gs.push(o);by[t]=o}by[t].it.push(i)}else gs[gi].it.push(i)})});
 if(c.ord&&c.ord.length)gs.sort(function(a,b){var x=c.ord.indexOf(a.n),y=c.ord.indexOf(b.n);return (x<0?99:x)-(y<0?99:y)});
 if(c.iord&&c.iord.length)gs.forEach(function(o){var seg=[],out=[];var fl=function(){seg.map(function(it,k){return[it,k]}).sort(function(a,b){var x=c.iord.indexOf(a[0][0]),y=c.iord.indexOf(b[0][0]);if(x<0&&y<0)return a[1]-b[1];if(x<0)return 1;if(y<0)return -1;return x-y}).forEach(function(a){out.push(a[0])});seg=[]};o.it.forEach(function(i){if(i[0].charAt(0)=='-'){fl();out.push(i)}else seg.push(i)});fl();o.it=out});
 return gs}
function applyCfg(c){var gs=build(c);MENU.length=0;gs.forEach(function(o){if(o.it.some(function(i){return i[0].charAt(0)!='-'}))MENU.push([o.n,o.it])})}
